//! Support for code generated by the derive macros. Not a public API.

use std::cell::Cell;

use bytes::BufMut;
pub use bytes::{Bytes, BytesMut};

use crate::{Decode, DecodeError, MAX_DEPTH};

pub use std::any::type_name;
pub use std::result::Result::{self, Err, Ok};

/// An envelope's header: version, compat version, body size.
pub const ENVELOPE_HEADER_LEN: usize = 6;

/// Writes an envelope whose body is whatever `body` appends.
///
/// The size is patched in after the body is written, as Redpanda does, so
/// encoding doesn't depend on `encoded_len` being right.
pub fn encode_envelope(
    buf: &mut BytesMut,
    version: u8,
    compat_version: u8,
    body: impl FnOnce(&mut BytesMut),
) {
    buf.put_u8(version);
    buf.put_u8(compat_version);
    let size_at = buf.len();
    buf.put_u32_le(0);
    body(buf);
    let size = buf.len() - size_at - 4;
    let size = u32::try_from(size).expect("shep-codec: envelope body exceeds u32::MAX bytes");
    buf[size_at..size_at + 4].copy_from_slice(&size.to_le_bytes());
}

/// Reads an envelope's header, checks that a reader at `version` /
/// `compat_version` may read it, and splits off its body.
///
/// Decoding fields from the returned body can't read past the envelope, and
/// whatever the reader leaves in it is skipped.
pub fn decode_envelope(
    buf: &mut Bytes,
    type_name: &'static str,
    version: u8,
    compat_version: u8,
) -> Result<Bytes, DecodeError> {
    let data_version = u8::decode(buf)?;
    let data_compat_version = u8::decode(buf)?;
    let size = u32::decode(buf)? as usize;
    if buf.len() < size {
        return Err(DecodeError::UnexpectedEnd {
            needed: size,
            remaining: buf.len(),
        });
    }
    if data_compat_version > version || data_version < compat_version {
        return Err(DecodeError::IncompatibleVersion {
            type_name,
            version: data_version,
            compat_version: data_compat_version,
            reader_version: version,
            reader_compat_version: compat_version,
        });
    }
    Ok(buf.split_to(size))
}

/// Decodes a field that old data must contain. One that encodes to nothing,
/// like `[u8; 0]`, is there even when the body is used up.
pub fn decode_field<T: Decode>(
    body: &mut Bytes,
    type_name: &'static str,
    field: &'static str,
) -> Result<T, DecodeError> {
    if body.is_empty() {
        return T::decode(body).map_err(|_| DecodeError::MissingField { type_name, field });
    }
    T::decode(body)
}

/// Decodes a `#[codec(default)]` field, which old data may lack.
pub fn decode_field_or_default<T: Decode + Default>(body: &mut Bytes) -> Result<T, DecodeError> {
    if body.is_empty() {
        return Ok(T::default());
    }
    T::decode(body)
}

thread_local! {
    static DEPTH: Cell<usize> = const { Cell::new(0) };
}

/// One level of derived-type nesting, released on drop.
pub struct DepthGuard(());

impl DepthGuard {
    pub fn enter() -> Result<DepthGuard, DecodeError> {
        DEPTH.with(|depth| {
            if depth.get() >= MAX_DEPTH {
                return Err(DecodeError::TooDeep);
            }
            depth.set(depth.get() + 1);
            Ok(DepthGuard(()))
        })
    }
}

impl Drop for DepthGuard {
    fn drop(&mut self) {
        DEPTH.with(|depth| depth.set(depth.get() - 1));
    }
}
